// Bentuk satu tugas
{
  id: "lq3k9z1ab2c",   // teks unik, dibuat otomatis
  teks: "Kerjakan PR matematika",
  selesai: false
}

// Seluruh aplikasi = satu array tugas + satu filter
let tugas = [ /* objek seperti di atas */ ];
let filter = "semua"; // "semua" | "aktif" | "selesai"

:root {
  --warna-utama: #2f6b3f;
  --warna-latar: #f4f5ef;
  --warna-kartu: #ffffff;
  --warna-teks: #1c1e1b;
  --warna-redup: #6b6f68;
  --sudut: 0.75rem;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  line-height: 1.5;
  color: var(--warna-teks);
  background: var(--warna-latar);
}

.wadah { max-width: 32rem; margin: 0 auto; padding: 2rem 1rem; }

h1 { margin: 0 0 1.5rem; font-size: 2rem; }

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

button, input { font: inherit; }

button {
  cursor: pointer;
  border: 0;
  border-radius: var(--sudut);
  padding: 0.6rem 1rem;
}

:focus-visible { outline: 3px solid var(--warna-utama); outline-offset: 2px; }

.form-tugas { display: flex; gap: 0.5rem; }
.form-tugas input {
  flex: 1;
  min-width: 0;
  padding: 0.6rem 0.8rem;
  border: 1px solid #8a8f86;
  border-radius: var(--sudut);
}
.form-tugas button { background: var(--warna-utama); color: #fff; font-weight: 600; }

.filter { display: flex; gap: 0.5rem; margin: 1rem 0; }
.filter button { background: transparent; color: var(--warna-redup); }
.filter button[aria-pressed="true"] { background: var(--warna-teks); color: #fff; }

.daftar-tugas { list-style: none; margin: 0; padding: 0; }

.tugas {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.75rem 1rem;
  margin-bottom: 0.5rem;
  background: var(--warna-kartu);
  border-radius: var(--sudut);
  box-shadow: 0 1px 4px rgb(0 0 0 / 0.06);
}
.tugas input { width: 1.25rem; height: 1.25rem; accent-color: var(--warna-utama); }
.tugas label { flex: 1; overflow-wrap: anywhere; }
.tugas.selesai label { text-decoration: line-through; color: var(--warna-redup); }

.hapus { background: transparent; color: #a33a2b; padding: 0.4rem 0.6rem; }
.hapus:hover { background: #fbe9e6; }

.kosong, .sisa { color: var(--warna-redup); text-align: center; }

const form = document.querySelector("#form-tugas");
const input = document.querySelector("#input-tugas");
const daftar = document.querySelector("#daftar-tugas");

// Satu-satunya sumber kebenaran: semua tugas ada di array ini.
let tugas = [];

function buatId() {
  return Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
}

function buatItem(t) {
  const li = document.createElement("li");
  li.className = "tugas";
  li.textContent = t.teks; // textContent, bukan innerHTML: aman dari teks berisi kode
  return li;
}

function render() {
  daftar.replaceChildren(...tugas.map(buatItem));
}

form.addEventListener("submit", (e) => {
  e.preventDefault(); // cegah halaman dimuat ulang
  const teks = input.value.trim();
  if (!teks) return;
  tugas.push({ id: buatId(), teks, selesai: false });
  input.value = "";
  input.focus();
  render();
});

render();

const form = document.querySelector("#form-tugas");
const input = document.querySelector("#input-tugas");
const daftar = document.querySelector("#daftar-tugas");

let tugas = [];

function buatId() {
  return Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
}

function buatItem(t) {
  const li = document.createElement("li");
  li.className = "tugas";
  li.classList.toggle("selesai", t.selesai);
  li.dataset.id = t.id;

  const cek = document.createElement("input");
  cek.type = "checkbox";
  cek.id = "cek-" + t.id;
  cek.checked = t.selesai;

  const label = document.createElement("label");
  label.htmlFor = cek.id;
  label.textContent = t.teks;

  const hapus = document.createElement("button");
  hapus.type = "button";
  hapus.className = "hapus";
  hapus.textContent = "Hapus";
  hapus.setAttribute("aria-label", "Hapus tugas: " + t.teks);

  li.append(cek, label, hapus);
  return li;
}

function render() {
  daftar.replaceChildren(...tugas.map(buatItem));
}

form.addEventListener("submit", (e) => {
  e.preventDefault();
  const teks = input.value.trim();
  if (!teks) return;
  tugas.push({ id: buatId(), teks, selesai: false });
  input.value = "";
  input.focus();
  render();
});

// Satu pendengar di <ul> untuk semua item (event delegation).
daftar.addEventListener("change", (e) => {
  if (!e.target.matches('input[type="checkbox"]')) return;
  const id = e.target.closest("li").dataset.id;
  const t = tugas.find((x) => x.id === id);
  t.selesai = e.target.checked;
  render();
  document.getElementById("cek-" + id)?.focus(); // fokus kembali untuk pengguna keyboard
});

daftar.addEventListener("click", (e) => {
  if (!e.target.matches(".hapus")) return;
  const id = e.target.closest("li").dataset.id;
  tugas = tugas.filter((x) => x.id !== id);
  render();
  input.focus();
});

render();

const KUNCI = "daftar-tugas";

const form = document.querySelector("#form-tugas");
const input = document.querySelector("#input-tugas");
const daftar = document.querySelector("#daftar-tugas");
const kosong = document.querySelector("#kosong");
const sisa = document.querySelector("#sisa");
const tombolFilter = document.querySelectorAll("[data-filter]");

let tugas = muat();
let filter = "semua";

function muat() {
  try {
    const data = JSON.parse(localStorage.getItem(KUNCI));
    return Array.isArray(data) ? data : [];
  } catch {
    return []; // data rusak: mulai dari daftar kosong
  }
}

function simpan() {
  localStorage.setItem(KUNCI, JSON.stringify(tugas));
}

function buatId() {
  return Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
}

function terlihat() {
  if (filter === "aktif") return tugas.filter((t) => !t.selesai);
  if (filter === "selesai") return tugas.filter((t) => t.selesai);
  return tugas;
}

function buatItem(t) {
  const li = document.createElement("li");
  li.className = "tugas";
  li.classList.toggle("selesai", t.selesai);
  li.dataset.id = t.id;

  const cek = document.createElement("input");
  cek.type = "checkbox";
  cek.id = "cek-" + t.id;
  cek.checked = t.selesai;

  const label = document.createElement("label");
  label.htmlFor = cek.id;
  label.textContent = t.teks;

  const hapus = document.createElement("button");
  hapus.type = "button";
  hapus.className = "hapus";
  hapus.textContent = "Hapus";
  hapus.setAttribute("aria-label", "Hapus tugas: " + t.teks);

  li.append(cek, label, hapus);
  return li;
}

function render() {
  const tampil = terlihat();
  daftar.replaceChildren(...tampil.map(buatItem));
  kosong.hidden = tampil.length > 0;

  const jumlahAktif = tugas.filter((t) => !t.selesai).length;
  sisa.textContent = jumlahAktif + " tugas belum selesai";

  tombolFilter.forEach((b) => {
    b.setAttribute("aria-pressed", String(b.dataset.filter === filter));
  });
}

// Setiap perubahan data lewat sini: simpan dulu, lalu gambar ulang.
function perbarui() {
  simpan();
  render();
}

form.addEventListener("submit", (e) => {
  e.preventDefault();
  const teks = input.value.trim();
  if (!teks) return;
  tugas.push({ id: buatId(), teks, selesai: false });
  input.value = "";
  input.focus();
  perbarui();
});

daftar.addEventListener("change", (e) => {
  if (!e.target.matches('input[type="checkbox"]')) return;
  const id = e.target.closest("li").dataset.id;
  const t = tugas.find((x) => x.id === id);
  t.selesai = e.target.checked;
  perbarui();
  document.getElementById("cek-" + id)?.focus();
});

daftar.addEventListener("click", (e) => {
  if (!e.target.matches(".hapus")) return;
  const id = e.target.closest("li").dataset.id;
  tugas = tugas.filter((x) => x.id !== id);
  perbarui();
  input.focus();
});

tombolFilter.forEach((b) => {
  b.addEventListener("click", () => {
    filter = b.dataset.filter;
    render(); // filter hanya tampilan, data tidak berubah
  });
});

render();

// Jalankan di tab Console DevTools

// Lihat isi yang tersimpan
JSON.parse(localStorage.getItem("daftar-tugas"));

// Simulasikan data rusak, lalu muat ulang halaman: aplikasi harus tetap jalan
localStorage.setItem("daftar-tugas", "ini bukan JSON");

// Bersihkan semuanya untuk mulai dari nol
localStorage.removeItem("daftar-tugas");
